}

/**
 * Extract the body of `function name(...) { ... }` (or the
 * `name: function(...) { ... }` object form) from a source, using
 * brace-depth counting that skips string literals and comments.
 * Returns null when the function is not present.
 */
function extractFunctionBody(src, name) {
    var declRe = new RegExp('(?:function\\s+' + name + '|' + name + '\\s*:\\s*function)\\s*\\(');
    var decl = declRe.exec(src);
    if (!decl) return null;
    var start = src.indexOf('{', decl.index);
    if (start === -1) return null;
    var depth = 0;
    var quote = null;
    for (var i = start; i < src.length; i++) {
        var c = src[i];
        if (quote) {
            if (c === '\\') { i++; continue; }
            if (c === quote) quote = null;
            continue;
        }
        if (c === "'" || c === '"' || c === '`') { quote = c; continue; }
        if (c === '{') depth++;
        else if (c === '}') {
            depth--;
            if (depth === 0) return src.substring(start, i + 1);
        }
    }
    return null;
}

