/**
 * Collect the js/common/ helper sources an action delegates to, following
 * local relative requires transitively while they stay inside a `common/`
 * directory. Cycle-protected; unresolvable or non-common requires are
 * skipped.
 */
function collectCommonDelegations(filePath, src, visited) {
    visited = visited || {};
    if (visited[filePath]) return [];
    visited[filePath] = true;

    var out = [];
    collectLocalRequires(src).forEach(function(reqPath) {
        var resolved = resolveLocalRequire(filePath, reqPath);
        if (resolved.indexOf('/common/') === -1) return;
        var helperSrc = readSource(resolved);
        if (!helperSrc) return;
        out.push({ path: resolved, src: helperSrc });
        collectCommonDelegations(resolved, helperSrc, visited).forEach(function(nested) {
            out.push(nested);
        });
    });
    return out;
}

