cd /home/runner/work/dmtools-agents/dmtools-agents && node -e "
const fs = require('fs');
const files = ['test_checkoutBranch.js','test_preCliDevelopmentSetup.js','test_preCliMobileTestAutomationSetup.js','test_preCliTestAutomationSetup.js','test_preCliTestReworkSetup.js','test_prepareTestPRForReview.js','test_storyTestAutomationRework.js','test_wave1bTrackers.js','test_wave2d1Tracker.js','test_wave2d3Tracker.js','test_baseBranchMarker.js','test_workingDir.js'];
const needsBS = new Set();
for (const d of ['js','js/common']) for (const f of fs.readdirSync(d)) {
  if (!f.endsWith('.js')) continue;
  const s = fs.readFileSync(d+'/'+f,'utf8');
  if (/require\(\s*['\"](?:\.\/)?(?:common\/)?branchSetup\.js['\"]/.test(s)) needsBS.add(d+'/'+f);
}
const plan = [];
for (const f of new Set(files)) {
  const p = 'js/unit-tests/'+f;
  const lines = fs.readFileSync(p,'utf8').split('\n');
  lines.forEach((line, i) => {
    if (!line.includes(\"'branchSetup.js': loadModule('js/common/branchSetup.js'\")) return;
    // candidate target: same line first
    let m = line.match(/loadModule\(\s*'(js\/[^']+)'/g) || [];
    let target = null, confident = false;
    const onSame = [...line.matchAll(/loadModule\(\s*'(js\/[^']+)'/g)].map(x=>x[1]).filter(x=>x!=='js/common/branchSetup.js');
    if (onSame.length >= 1) { target = onSame[0]; confident = true; }
    else {
      // nearest previous non-empty line
      for (let j = i-1; j >= 0; j--) {
        const pl = lines[j].trim();
        if (!pl) continue;
        const mm = [...pl.matchAll(/loadModule\(\s*'(js\/[^']+)'/g)].map(x=>x[1]).filter(x=>x!=='js/common/branchSetup.js');
        if (mm.length >= 1) { target = mm[0]; confident = true; }
        break;
      }
    }
    if (confident && target && !needsBS.has(target)) plan.push({p, line: i+1, target});
  });
}
console.log('CONFIDENT-UNUSED count:', plan.length);
plan.forEach(u=>console.log(u.p+':'+u.line, '->', u.target));
fs.writeFileSync('/tmp/removal_plan.json', JSON.stringify(plan));
"

