const fs = require('fs');
const files = ['js/factory/mark_job_done_publish.js', 'js/factory/review_verdict_publish.js', 'js/factory/token_usage_publish.js'];

const Q = "v === undefined || v === null || v === ''";
const R = "v === undefined || v === null ? '' : String(v)";

const oldEnv = [
    'function envValue(name) {',
    '    try {',
    "        if (typeof java !== 'undefined' && java && java.lang &&",
    "            java.lang.System && typeof java.lang.System.getenv === 'function') {",
    '            var v = java.lang.System.getenv(name);',
    "            return (v === null || v === undefined) ? '' : String(v);",
    '        }',
    '    } catch (e) { /* no env bridge on this runtime */ }',
    "    return '';",
    '}'
].join('\n');

const newEnv = [
    '// The java.lang.System env bridge when this runtime has one, else null.',
    '// Guarded on purpose: QuickJS has no java bridge, so every access is',
    "// wrapped and missing env simply yields '' (the caller defaults take over).",
    'function _envBridge() {',
    '    try {',
    "        if (typeof java !== 'undefined' && java && java.lang &&",
    "            java.lang.System && typeof java.lang.System.getenv === 'function') {",
    '            return java.lang.System;',
    '        }',
    '    } catch (e) { /* no env bridge on this runtime */ }',
    '    return null;',
    '}',
    '',
    'function envValue(name) {',
    '    var system = _envBridge();',
    "    if (!system) return '';",
    '    var v = system.getenv(name);',
    "    return (v === null || v === undefined) ? '' : String(v);",
    '}',
    '',
    'function _isBlank(v) {',
    '    return ' + Q + ';',
    '}'
].join('\n');

const oldPick = [
    '    function pick(key, envName, dflt) {',
    '        var v = custom[key];',
    '        if (' + Q + ') v = env(envName);',
    '        if (' + Q + ') v = dflt;',
    '        return ' + R + ';',
    '    }'
].join('\n');

const newPick = [
    '    function pick(key, envName, dflt) {',
    '        var v = custom[key];',
    '        if (_isBlank(v)) v = env(envName);',
    '        if (_isBlank(v)) v = dflt;',
    '        return ' + R + ';',
    '    }'
].join('\n');

files.forEach(function(f) {
    let s = fs.readFileSync(f, 'utf8');
    if (!s.includes(oldEnv)) { console.error('ENV MISMATCH', f); process.exit(1); }
    if (!s.includes(oldPick)) { console.error('PICK MISMATCH', f); process.exit(1); }
    s = s.replace(oldEnv, newEnv).replace(oldPick, newPick);
    fs.writeFileSync(f, s);
    console.log('patched', f);
});

