function _ticketPage(rawPage, listField) {
    var page = _parseJson(rawPage);
    var list = page && typeof page === 'object' && !Array.isArray(page)
        ? (page[listField] || [])
        : (Array.isArray(page) ? page : []);
    var out = [];
    for (var i = 0; i < list.length; i++) {
        var n = normalizeTicket(list[i]);
        if (n) out.push(n);
    }
    return out;
}

